    static int[] readInts(Scanner sc){ String line = sc.hasNextLine() ? sc.nextLine() : ""; line = line.trim(); if (line.isEmpty()) return new int[0]; String[] t = line.split("\\s+"); int[] a = new int[t.length]; for (int i=0;i<t.length;i++) a[i]=Integer.parseInt(t[i]); return a; }
    static ListNode buildAppend(int[] a){
        ListNode dummy = new ListNode(0), t = dummy;
        for (int x : a) {
            ____
            t = t.next;
        }
        return dummy.next;
    }
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        ListNode h = buildAppend(readInts(sc));
        StringBuilder sb = new StringBuilder();
        while (h != null) { if (sb.length()>0) sb.append(' '); sb.append(h.val); h = h.next; }
        System.out.println(sb.toString());
    }
}

